package com.bank.notify;

import java.util.*;
import java.util.logging.*;

public class NotificationDemo {
    private static final Logger log = Logger.getLogger("Notify");
    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        UserPreferenceStore prefs = new UserPreferenceStore();
        prefs.set("SAV2001", List.of("PUSH", "SMS"));   // Rajesh
        prefs.set("CUR3001", List.of("SMS", "EMAIL"));  // Priya

        TemplateEngine templates = new TemplateEngine();
        NotificationQueue queue = new NotificationQueue();
        NotificationDispatcher dispatcher = new NotificationDispatcher(prefs, templates);

        // Publish a NORMAL transfer confirmation and a HIGH fraud alert
        queue.publish(new NotificationEvent("evt-1", "SAV2001", "TRANSFER_SUCCESS",
            Map.of("name","Rajesh","amount","50000","to","CUR3001"), Priority.NORMAL));
        queue.publish(new NotificationEvent("evt-2", "CUR3001", "FRAUD_ALERT",
            Map.of("name","Priya"), Priority.HIGH));

        // Dispatcher drains the queue — HIGH priority first
        NotificationEvent e;
        while ((e = queue.poll()) != null) {
            dispatcher.dispatch(e);
        }
    }
}

