package com.bank.notify;

import java.util.Map;

public class NotificationEvent {
    private final String id;          // stable id for idempotency
    private final String userId;
    private final String templateKey;
    private final Map<String,String> data;
    private final Priority priority;

    public NotificationEvent(String id, String userId, String templateKey,
                             Map<String,String> data, Priority priority) {
        this.id = id; this.userId = userId; this.templateKey = templateKey;
        this.data = data; this.priority = priority;
    }
    public String getId() { return id; }
    public String getUserId() { return userId; }
    public String getTemplateKey() { return templateKey; }
    public Map<String,String> getData() { return data; }
    public Priority getPriority() { return priority; }
}
