package com.bank.notify;

import java.util.*;

// Priority queue: HIGH drains before NORMAL before LOW.
public class NotificationQueue {
    private final PriorityQueue<NotificationEvent> pq =
        new PriorityQueue<>(Comparator.comparingInt(e -> e.getPriority().ordinal()));

    public void publish(NotificationEvent e) { pq.offer(e); }
    public NotificationEvent poll() { return pq.poll(); }
}
```

