package com.bank.notify;

import java.util.*;

public class TemplateEngine {
    private final Map<String,String> templates = new HashMap<>();
    public TemplateEngine() {
        templates.put("TRANSFER_SUCCESS", "Dear {name}, Rs.{amount} transferred to {to}.");
        templates.put("FRAUD_ALERT", "Dear {name}, suspicious activity detected. Call us now.");
    }
    public String render(String key, Map<String,String> data) {
        String t = templates.getOrDefault(key, "{name}, you have a notification.");
        for (Map.Entry<String,String> en : data.entrySet())
            t = t.replace("{" + en.getKey() + "}", en.getValue());
        return t;
    }
}
