package com.bank.notify;

import java.util.*;

public class UserPreferenceStore {
    private final Map<String,List<String>> channels = new HashMap<>();
    public void set(String userId, List<String> ordered) { channels.put(userId, ordered); }
    public List<String> channelsFor(String userId) {
        return channels.getOrDefault(userId, List.of("EMAIL"));
    }
}
