package com.bank.notify;

import java.util.logging.*;

public class ChannelSender {
    private static final Logger log = Logger.getLogger("Notify");
    private int smsAttempts = 0; // simulate SMS failing the first time

    // returns true if the provider accepted the message
    public boolean send(String channel, String userId, String body) {
        if ("SMS".equals(channel) && smsAttempts++ == 0) {
            log.warning(() -> "SMS provider temporary failure for " + userId);
            return false;   // transient failure triggers retry
        }
        log.info(() -> channel + " -> " + userId + ": " + body);
        return true;
    }
}
